item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['bioconductor-apeglm','bioconductor-ashr']:
 u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=10&onlyActiveTags=true'
 try:
  with urllib.request.urlopen(u, timeout=30) as r: x=json.load(r)
  print(repo)
  for t in x.get('tags',[])[:5]: print(t['name'])
 except Exception as e: print(type(e).__name__)
PY"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['bioconductor-apeglm','bioconductor-ashr']:
 u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=10&onlyActiveTags=true'
 try:
  with urllib.request.urlopen(u, timeout=30) as r: x=json.load(r)
  print(repo)
  for t in x.get('tags',[])[:5]: print(t['name'])
 except Exception as e: print(type(e).__name__)
PY"

